#!/usr/bin/env python3
"""contract.json -> stmp/dispatch.py. Generated file, committed on purpose.

The table a reviewer reads at the pinned SHA must be the table the plugin loads,
so it is checked in and CI proves regeneration is a no-op.

Usage
    python3 tools/generate.py
    python3 tools/generate.py --check
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CONTRACT = ROOT / "contract.json"
TARGET = ROOT / "stmp" / "dispatch.py"

HEADER = '''"""Generated by tools/generate.py from contract.json. Do not edit.

`python3 tools/generate.py --check` fails when this file and contract.json
disagree, so a hand edit here is caught before it can ship.
"""

from __future__ import annotations

CONTRACT_VERSION = {version}
ROUTE_COUNT = {route_count}

#: Routes that run with no approval modal. Named in the tool descriptions too:
#: an exemption a caller cannot see is a bypass, not a design.
EXEMPT = frozenset({{{exempt}}})

#: tool -> action -> (method, path)
DISPATCH: dict[str, dict[str, tuple[str, str]]] = {{
{dispatch}}}
'''


def render(contract: dict) -> str:
    tools = contract["tools"]
    lines: list[str] = []
    for tool in sorted(tools):
        actions = tools[tool]["actions"]
        lines.append(f'    "{tool}": {{')
        for action in sorted(actions):
            entry = actions[action]
            lines.append(
                f'        "{action}": ("{entry["method"]}", "{entry["path"]}"),'
            )
        lines.append("    },")
    exempt = ", ".join(f'"{route}"' for route in sorted(contract["exempt"]))
    return HEADER.format(
        version=contract["contract_version"],
        route_count=contract["route_count"],
        exempt=exempt,
        dispatch="\n".join(lines) + "\n",
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the file is stale")
    args = parser.parse_args(argv)

    if not CONTRACT.exists():
        print("contract.json is missing; run tools/sync_contract.py", file=sys.stderr)
        return 1

    contract = json.loads(CONTRACT.read_text(encoding="utf-8"))
    rendered = render(contract)

    if args.check:
        if not TARGET.exists():
            print(f"{TARGET.name} is missing; run tools/generate.py", file=sys.stderr)
            return 1
        if TARGET.read_text(encoding="utf-8") != rendered:
            print(
                "stmp/dispatch.py is stale; run tools/generate.py and commit the result",
                file=sys.stderr,
            )
            return 1
        print(
            f"dispatch check OK: v{contract['contract_version']}, "
            f"{contract['route_count']} routes across {len(contract['tools'])} tools"
        )
        return 0

    TARGET.write_text(rendered, encoding="utf-8")
    print(
        f"wrote {TARGET.relative_to(ROOT)}: v{contract['contract_version']}, "
        f"{contract['route_count']} routes across {len(contract['tools'])} tools"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
